import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (t-test p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
            if p_val < 0.05:
                sig_features.append((fid, abs(t_stat)))

    # Sort by effect size
    sig_features.sort(key=lambda x: x[1], reverse=True)

    # Check for product terms among top features
    top_fids = [f[0] for f in sig_features[:10]]

    # Look for correlated pairs with |r| >= 0.6
    candidates = []
    for i, fid1 in enumerate(top_fids):
        for j, fid2 in enumerate(top_fids[i+1:], i+1):
            col1_idx = feats.column(fid1)
            col2_idx = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1_idx], feats.x[:, col2_idx])[0,1]
            if abs(corr) >= 0.6:
                candidates.append((fid1, fid2))

    # If we have candidate pairs, form a product term
    if candidates:
        # Use the pair with highest correlation
        a, b = candidates[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={a: 1.0, b: 1.0}
        )

    # Otherwise, use top individual features
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return top 1-3 individual features
    n_drivers = min(len(sig_features), MAX_DRIVERS)
    drivers = tuple(f[0] for f in sig_features[:n_drivers])
    columns = drivers

    # Simple loading weights based on effect size
    loadings = {}
    for i, (fid, _) in enumerate(sig_features[:n_drivers]):
        loadings[fid] = float(i+1)  # Higher effect gets higher weight

    return Design(
        drivers=drivers,
        columns=columns,
        products=(),
        loadings=loadings
    )

